      "text": "Returns 0xffffffffffffffff when out_cap < (len + 2) / 3 << 2.",
      "asserted_values": ["0xffffffffffffffff"],
      "confidence": 1.0,
      "io": {
        "when": "out_cap < (len + 2) / 3 << 2",
        "returns": "0xffffffffffffffff"
      }
    },
    {
      "id": "3",
      "type": "SIDE",
      "text": "Writes Base64 encoded characters to out[0..<len + 2 / 3 * 4].",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "4",
      "type": "CF",
      "text": "Loops over input data in chunks of 3 bytes.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "5",
      "type": "CF",
      "text": "Handles cases where len is not a multiple of 3 by appending '=' characters.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_07(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < (len + 2) / 3 << 2) {\n    return 0xffffffffffffffff;\n  }\n\n  const char *base64_chars = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n\n  size_t o = 0;\n  for (size_t i = 0; i + 3 <= len; i += 3) {\n    uint32_t uVar4 = (uint)in[i] << 0x10 | (uint)in[i + 1] << 8;\n    uint8_t bVar2 = in[i + 2];\n\n    out[o++] = base64_chars[in[i] >> 2];\n    out[o++] = base64_chars[(uVar4 & 0x3f000) >> 0xc];\n    out[o++] = base64_chars[(bVar2 | uVar4) >> 6 & 0x3f];\n    out[o++] = base64_chars[bVar2 & 0x3f];\n  }\n\n  if (len - i == 1) {\n    uint8_t bVar2 = in[i];\n    out[o++] = base64_chars[bVar2 >> 2];\n    out[o++] = base64_chars[(bVar2 & 3) << 4];\n    out[o++] = '=';\n    out[o++] = '=';\n  } else if (len - i == 2) {\n    uint8_t bVar2 = in[i];\n    uint8_t bVar3 = in[i + 1];\n    out[o++] = base64_chars[bVar2 >> 2];\n    out[o++] = base64_chars[((uint)bVar3 << 8 | (uint)bVar2 << 0x10) >> 0xc & 0x3f];\n    out[o++] = base64_chars[((uint)bVar3 << 8 & 0xfc0) >> 6];\n    out[o++] = '=';\n  }\n\n  return o;\n}"
}
